// The Service Worker's media bundle (Item 3, phase 3B).
//
// public/sw-media-bundle.js is GENERATED by scripts/build-sw-media-bundle.mjs
// from public/js/sw-media/bundle-entry.js. It is a shipped file:
// scripts/build-sw-manifest.mjs hashes it, the worker verifies that hash
// while precaching and refuses to install when the served bytes differ.
//
// What is checked here (no browser):
//   1. the committed bundle is byte-identical to a fresh rebuild
//   2. the bundle carries exactly ONE chunkNonce and exactly ONE container
//      header literal (in the hex form AND in the decimal form)
//   3. public/sw.js declares no top-level binding named `WireMedia`
//   4. the manifest lists the bundle with the SHA-256 of its bytes and
//      `build-sw-manifest.mjs --check` is green
//
//   node --test tests/crypto/sw-media-bundle.test.mjs

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const BUILD = path.join(ROOT, 'scripts', 'build-sw-media-bundle.mjs');
const MANIFEST_BUILD = path.join(ROOT, 'scripts', 'build-sw-manifest.mjs');
const BUNDLE = path.join(ROOT, 'public', 'sw-media-bundle.js');
const SW = path.join(ROOT, 'public', 'sw.js');
const MANIFEST = path.join(ROOT, 'public', 'sw-manifest.js');

const REBUILD_HINT = 'Rebuild it with: node scripts/build-sw-media-bundle.mjs';

const tmpDirs = [];
process.on('exit', () => {
    for (const dir of tmpDirs) {
        try { fs.rmSync(dir, { recursive: true, force: true }); } catch { /* best effort */ }
    }
});

function tmpDir() {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'wire-bundle-test-'));
    tmpDirs.push(dir);
    return dir;
}

/** The header bytes as they may be written down: hex or decimal. */
const HEADER_HEX = '0x57, 0x41, 0x54, 0x31';
const HEADER_DECIMAL = '87, 65, 84, 49';

function countOccurrences(haystack, needle) {
    let count = 0;
    let at = haystack.indexOf(needle);
    while (at !== -1) {
        count += 1;
        at = haystack.indexOf(needle, at + needle.length);
    }
    return count;
}

/**
 * Removes comments and string bodies, so that the remaining text is code.
 * Used for the "top-level declaration" check.
 */
function stripCommentsAndStrings(source) {
    let out = '';
    let i = 0;
    let state = 'code';

    while (i < source.length) {
        const c = source[i];
        const n = source[i + 1];

        if (state === 'code') {
            if (c === '/' && n === '/') { state = 'line'; i += 2; continue; }
            if (c === '/' && n === '*') { state = 'block'; i += 2; continue; }
            if (c === "'") { state = 'single'; out += ' '; i += 1; continue; }
            if (c === '"') { state = 'double'; out += ' '; i += 1; continue; }
            if (c === '`') { state = 'template'; out += ' '; i += 1; continue; }
            out += c;
            i += 1;
            continue;
        }

        if (state === 'line') {
            if (c === '\n') { state = 'code'; out += c; }
            i += 1;
            continue;
        }

        if (state === 'block') {
            if (c === '*' && n === '/') { state = 'code'; i += 2; continue; }
            if (c === '\n') out += c;
            i += 1;
            continue;
        }

        if (c === '\\') { out += '  '; i += 2; continue; }
        if ((state === 'single' && c === "'") ||
            (state === 'double' && c === '"') ||
            (state === 'template' && c === '`')) {
            state = 'code';
        }
        out += (c === '\n') ? '\n' : ' ';
        i += 1;
    }

    return out;
}

/** The brace depth at every character offset of a source. */
function braceDepths(source) {
    const depths = new Array(source.length + 1);
    let depth = 0;
    for (let i = 0; i <= source.length; i += 1) {
        depths[i] = depth;
        if (source[i] === '{') depth += 1;
        else if (source[i] === '}') depth -= 1;
    }
    return depths;
}

/** The names bound at the top level of a classic script. */
function topLevelBindings(source) {
    const code = stripCommentsAndStrings(source);
    const depths = braceDepths(code);
    const names = [];
    const re = /(?:^|[\s;{}])(?:var|let|const|function|class)\s+([A-Za-z_$][\w$]*)/g;
    let m;
    while ((m = re.exec(code)) !== null) {
        const at = m.index + (m[0].length - m[1].length - 1);
        if (depths[at] === 0) names.push(m[1]);
    }
    return names;
}

// ---------------------------------------------------------------------- 1
test('the committed bundle is byte-identical to a fresh rebuild', () => {
    assert.ok(fs.existsSync(BUNDLE), `public/sw-media-bundle.js is missing. ${REBUILD_HINT}`);

    const out = path.join(tmpDir(), 'sw-media-bundle.js');
    const run = spawnSync(process.execPath, [BUILD, '--outfile', out], { encoding: 'utf8' });

    assert.equal(run.status, 0, `the bundle build failed:\n${run.stderr}\n${run.stdout}`);

    const fresh = fs.readFileSync(out);
    const committed = fs.readFileSync(BUNDLE);

    assert.deepEqual(
        fresh,
        committed,
        `public/sw-media-bundle.js is not what the build script produces. ${REBUILD_HINT}`
    );
});

test('the build script reports the committed bundle as current', () => {
    const run = spawnSync(process.execPath, [BUILD, '--check'], { encoding: 'utf8' });
    assert.equal(run.status, 0, `build-sw-media-bundle.mjs --check failed:\n${run.stderr}\n${run.stdout}`);
    assert.match(run.stdout, /sw-media-bundle\.js is current/);
});

// ---------------------------------------------------------------------- 2
test('the bundle carries exactly one chunkNonce and one container header literal', () => {
    const bundle = fs.readFileSync(BUNDLE, 'utf8');

    const nonces = countOccurrences(bundle, 'function chunkNonce');
    assert.equal(
        nonces,
        1,
        `the bundle must contain exactly one chunkNonce implementation, found ${nonces}. ` +
        'A second copy would mean the nonce layout is no longer single-sourced.'
    );

    const hex = countOccurrences(bundle, HEADER_HEX);
    const decimal = countOccurrences(bundle, HEADER_DECIMAL);
    const headers = hex + decimal;

    assert.equal(
        headers,
        1,
        `the bundle must contain exactly one container header literal ` +
        `(hex: ${hex}, decimal: ${decimal}). A second copy of the header bytes ` +
        'means the container format could drift apart from the writer.'
    );
});

// ---------------------------------------------------------------------- 3
test('public/sw.js declares no top-level binding named WireMedia', () => {
    const source = fs.readFileSync(SW, 'utf8');
    const bindings = topLevelBindings(source);

    const clash = bindings.filter((name) => name === 'WireMedia');
    assert.deepEqual(
        clash,
        [],
        'public/sw.js must not bind the name WireMedia at the top level: the generated ' +
        'bundle publishes itself as `var WireMedia` in the same global scope, and a ' +
        'top-level `let`/`const` with the same name makes the whole worker script ' +
        'fail to evaluate.'
    );
});

// ---------------------------------------------------------------------- 4
test('the manifest lists the bundle with the SHA-256 of its bytes', () => {
    const manifest = fs.readFileSync(MANIFEST, 'utf8');
    const entry = /"url": "\/sw-media-bundle\.js",\s*"rev": "([0-9a-f]{64})"/.exec(manifest);

    assert.ok(
        entry,
        'public/sw-manifest.js does not list /sw-media-bundle.js. ' +
        'Regenerate it with: node scripts/build-sw-manifest.mjs'
    );

    const actual = createHash('sha256').update(fs.readFileSync(BUNDLE)).digest('hex');
    assert.equal(
        entry[1],
        actual,
        'the manifest hash of the bundle does not match its bytes. ' +
        'Regenerate it with: node scripts/build-sw-manifest.mjs'
    );
});

test('the shipped sw-manifest.js is current', () => {
    const run = spawnSync(process.execPath, [MANIFEST_BUILD, '--check'], { encoding: 'utf8' });
    assert.equal(
        run.status,
        0,
        `public/sw-manifest.js is out of date:\n${run.stderr}\n${run.stdout}\n` +
        'Regenerate it with: node scripts/build-sw-manifest.mjs'
    );
});
